import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';
class AppShell extends StatelessWidget{final StatefulNavigationShell shell;const AppShell({super.key,required this.shell});@override Widget build(BuildContext context)=>Scaffold(body:shell,bottomNavigationBar:NavigationBar(selectedIndex:shell.currentIndex,onDestinationSelected:(i)=>shell.goBranch(i,initialLocation:i==shell.currentIndex),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home_rounded),label:'Bosh sahifa'),NavigationDestination(icon:Icon(Icons.live_tv_outlined),selectedIcon:Icon(Icons.live_tv),label:'TV'),NavigationDestination(icon:Icon(Icons.movie_outlined),selectedIcon:Icon(Icons.movie),label:'Kinolar'),NavigationDestination(icon:Icon(Icons.search),selectedIcon:Icon(Icons.manage_search),label:'Qidiruv'),NavigationDestination(icon:Icon(Icons.person_outline),selectedIcon:Icon(Icons.person),label:'Profil')]));}
